def fix_spaces(text):
    if len(text) == 0:
        return text

    result = []
    i = 0
    while i < len(text):
        char = text[i]

        # Check for consecutive spaces starting at current position
        space_count = 0
        j = i
        while j < len(text) and text[j] == ' ':
            space_count += 1
            j += 1

        if space_count > 2:
            result.append('-')
            # Skip all the spaces we just counted
            i = j - 1 
        elif char != ' ':
            result.append(char)
        else:
            # Single or double space -> replace with underscore
            result.append('_')

        if text[i] == ' ':
            i += 1

    return ''.join(result)

